let testsPrepared = false, testOriginal = null, selectedTestId = 'literasi', testsTab = 'questions', testDraft = null;
let testQuestionBank = [];
const testBankFormats = {mcq:'Pilihan ganda',multi_answer:'Jawaban lebih dari satu',essay:'Esai',multi_blank:'Isian majemuk',true_false:'Benar / salah'};
let testQuery = '', testSubject = '', testTopic = '', testPreviewIndex = 0, testPreviewAll = false;
function prepareTests(){
  if(testsPrepared)return;
  if(!testOriginal)testOriginal=structuredClone(library);
  library.forEach(t=>{t.topic=t.topic||({literasi:'Pemahaman bacaan',matematika:'Data & bilangan',english:'Reading comprehension'}[t.id]||'Umum');t.sectionType=t.sectionType??(t.id==='matematika'?'':'reading');t.audioUrl=t.audioUrl||'';t.audioLimit=t.audioLimit??'';});
  testQuestionBank=structuredClone([...new Map(library.flatMap(t=>t.questions.map(q=>({...q,topic:t.topic,format:q.format||'mcq'}))).map(q=>[q.id,q])).values()]);
  testQuestionBank.push({id:'bank-long',topic:'Pemahaman bacaan',format:'mcq',body:'Pemerintah kota menguji penutupan jalan bagi kendaraan pada akhir pekan selama tiga bulan. Pada bulan pertama, jumlah pengunjung meningkat dan beberapa pedagang melaporkan kenaikan penjualan. Namun, warga di sekitar lokasi mengeluhkan kemacetan di jalan alternatif. Sebagian pengunjung juga kesulitan menemukan akses transportasi umum menuju lokasi. Tim evaluasi kemudian membandingkan jumlah pengunjung, pendapatan pedagang, keluhan warga, dan kemudahan akses sebelum serta sesudah uji coba. Mereka menyarankan penambahan rute angkutan umum dan pengaturan jalan alternatif sebelum kebijakan diterapkan secara permanen. Berdasarkan informasi tersebut, kesimpulan manakah yang paling tepat untuk menjadi dasar keputusan pemerintah kota?',options:['Evaluasi manfaat dan dampak akses sebelum menetapkan kebijakan.','Terapkan permanen hanya berdasarkan kenaikan pengunjung.','Abaikan keluhan warga karena penjualan meningkat.','Hentikan seluruh kegiatan tanpa evaluasi.']});
  testsPrepared=true;
}
function resetTestPrototype(){if(testOriginal)library.splice(0,library.length,...structuredClone(testOriginal));testsPrepared=false;testQuestionBank=[];testDraft=null;selectedTestId='literasi';testsTab='questions';testQuery='';testSubject='';testTopic='';}
function savedTest(){return test(selectedTestId);}
function testFields(t){return {title:t.title,subject:t.subject,topic:t.topic,duration:t.duration,sectionType:t.sectionType,material:t.material||'',instructions:t.instructions||'',audioUrl:t.audioUrl||'',audioLimit:t.audioLimit??''};}
function testSettingsDirty(){return !!testDraft&&JSON.stringify(testDraft)!==JSON.stringify(testFields(savedTest()));}
function openTestPage(id){prepareTests();if(!test(id))return;selectedTestId=id;testDraft=testFields(savedTest());testsTab='questions';route('tests-detail');}
function renderTests(){prepareTests();if(view==='tests-list')return testsList();if(!savedTest())selectedTestId=library[0].id;if(!testDraft)testDraft=testFields(savedTest());return testsDetail();}
function testsList(){const subjects=[...new Set(library.map(t=>t.subject))],topics=[...new Set(library.filter(t=>!testSubject||t.subject===testSubject).map(t=>t.topic))];return shell(`${pageHead('Penyusun Tes','Buat dan kelola tes untuk bank soal.',button(`${icon('plus',15)} Tes baru`,'test-create','primary'),'exam')}<div class="admin-list-toolbar tests-toolbar"><div class="admin-list-search">${icon('search',16)}<input data-slot="input" id="tests-list-search" type="search" aria-label="Cari tes" placeholder="Cari tes..." value="${esc(testQuery)}"><button class="admin-search-clear" data-action="test-clear-search" aria-label="Hapus pencarian tes" ${testQuery?'':'hidden'}>${icon('close',16)}</button></div>${button(`${icon('settings',15)} Filter${testSubject||testTopic?' ('+[testSubject,testTopic].filter(Boolean).length+')':''}`,'test-filters','','aria-expanded="false" aria-controls="tests-filter-panel"')}<span id="tests-count" class="small muted" aria-live="polite">${library.length} tes</span><div id="tests-filter-panel" class="card tests-filter-panel" hidden><h3>Filter tes</h3><label>Mata pelajaran<select id="tests-subject"><option value="">Semua mata pelajaran</option>${subjects.map(s=>`<option ${testSubject===s?'selected':''}>${esc(s)}</option>`).join('')}</select></label><label>Topik<select id="tests-topic"><option value="">Semua topik</option>${topics.map(t=>`<option ${testTopic===t?'selected':''}>${esc(t)}</option>`).join('')}</select></label><div class="row between">${button('Reset filter','test-clear-filters')}${button('Tampilkan tes','test-apply-filters','primary')}</div></div></div><div class="tests-chips">${[['subject',testSubject],['topic',testTopic]].filter(([,v])=>v).map(([key,value])=>`<span class="badge gray">${esc(value)}<button data-action="test-clear-filter" data-key="${key}" aria-label="Hapus filter ${esc(value)}">×</button></span>`).join('')}</div><div class="admin-table-scroll mt"><table class="admin-table"><thead><tr><th>Tes</th><th>Mata pelajaran / topik</th><th>Soal</th><th>Durasi</th><th>Materi & audio</th></tr></thead><tbody>${library.map(t=>`<tr data-test-row="${t.id}"><td><button class="exam-link" data-action="test-open" data-id="${t.id}">${esc(t.title)}</button></td><td>${esc(t.subject)}<small>${esc(t.topic)}</small></td><td>${t.questions.length} soal</td><td>${t.duration} menit</td><td>${t.material?'Materi bersama':'Tanpa materi bersama'}<small>${t.questions.some(q=>q.material)?'Ada materi per soal':t.audioUrl?'Audio section':'Tanpa materi per soal'}</small></td></tr>`).join('')}<tr id="tests-empty" hidden><td colspan="5" class="admin-table-empty">Tidak ada tes yang cocok.</td></tr></tbody></table></div><p class="small muted mt">Tes adalah sumber soal, materi, dan durasi. Susunan section serta cara pengerjaan ditentukan di Ujian.</p>`);}
function filterTestsList(){const q=testQuery.trim().toLocaleLowerCase('id-ID');let count=0;document.querySelectorAll('[data-test-row]').forEach(row=>{const t=test(row.dataset.testRow);row.hidden=!t.title.toLocaleLowerCase('id-ID').includes(q)||!!testSubject&&t.subject!==testSubject||!!testTopic&&t.topic!==testTopic;if(!row.hidden)count++;});$('#tests-count').textContent=`${count} tes`;$('#tests-empty').hidden=count>0;const clear=$('[data-action="test-clear-search"]');if(clear)clear.hidden=!testQuery;}
function testsDetail(){const t=savedTest(),used=exam.sections.some(s=>s.id===t.id),dirty=testSettingsDirty();return shell(`<button class="text-button back" data-action="tests-list">${icon('back',14)} Penyusun Tes</button>${pageHead(t.title,`${esc(t.subject)} · ${esc(t.topic)}`,`${button(`${icon('eye',15)} Pratinjau`,'test-preview','',dirty||!t.questions.length?'disabled':'')}${button('Simpan pengaturan','test-save','primary',dirty?'':'disabled')}`,'exam')}<div class="tests-detail-meta"><span>${icon('exam',15)} ${t.questions.length} soal</span><span>${icon('clock',15)} ${t.duration} menit</span><span>${icon('book',15)} ${used?'Dipakai pada 1 ujian contoh':'Belum dipasang pada ujian contoh'}</span><span class="tests-save-state" role="status">${dirty?'Ada pengaturan belum disimpan':'Pengaturan tersimpan'}</span></div><div class="tests-source-note">${icon('book',18)}<p>Satu Tes dapat digunakan di beberapa ujian. Perubahan soal atau materi berlaku pada ujian yang memakai Tes ini, termasuk sesi berjalan. Durasi sesi yang sudah dimulai tetap mengikuti durasi saat sesi dibuat.</p></div><nav class="tabs" aria-label="Detail tes">${[['questions',`Soal (${t.questions.length})`],['content','Materi & instruksi'],['settings','Informasi tes']].map(([key,label])=>`<button data-action="test-tab" data-key="${key}" class="${testsTab===key?'active':''}">${label}</button>`).join('')}</nav>${testsTab==='questions'?testsQuestions(t):testsTab==='content'?testsContent():testsSettings()}`);}
function testsQuestions(t){const own=t.questions.filter(q=>q.material).length;return `<div class="tests-question-layout"><section class="card"><div class="tests-questions-head"><div><h2>Susunan soal</h2><p class="small muted mt-sm">Urutan disimpan saat kamu memindahkan atau melepas soal.</p></div>${button(`${icon('plus',14)} Dari bank soal`,'test-bank','primary')}</div>${t.questions.length?`<div class="tests-question-scroll"><table class="admin-table tests-question-table"><thead><tr><th>Urutan</th><th>Soal</th><th>Format</th><th>Materi</th><th>Aksi</th></tr></thead><tbody>${t.questions.map((q,i)=>`<tr><td><div class="tests-question-order"><span class="number">${i+1}</span><span class="section-actions"><button data-action="test-move" data-id="${q.id}" data-direction="-1" aria-label="Naikkan soal ${i+1}" ${i?'':'disabled'}>↑</button><button data-action="test-move" data-id="${q.id}" data-direction="1" aria-label="Turunkan soal ${i+1}" ${i===t.questions.length-1?'disabled':''}>↓</button></span></div></td><td><p class="tests-question-body">${esc(q.body)}</p></td><td>${badge('Pilihan ganda','gray')}</td><td>${q.material?badge('Materi sendiri','warn'):'Materi bersama'}</td><td><div class="tests-row-actions">${button(icon('eye',14),'test-question-preview','square',`data-id="${q.id}" aria-label="Lihat soal ${i+1}"`)} ${button(icon('trash',14),'test-detach','square danger',`data-id="${q.id}" aria-label="Lepas soal ${i+1} dari Tes" title="Lepas dari Tes"`)}</div></td></tr>`).join('')}</tbody></table></div>`:`<div class="tests-empty">${icon('exam',28)}<h3>Belum ada soal</h3><p class="small muted">Pilih soal dari bank untuk menyusun Tes ini.</p></div>`}</section><aside class="stack tests-sidebar"><section class="card card-body"><h2>Materi bersama</h2><div class="tests-material-summary rich-content">${t.material?cleanTestHTML(t.material):'<p class="muted">Belum ada materi bersama untuk Tes ini.</p>'}</div><p class="small muted">Menjadi acuan saat soal tidak memiliki materi sendiri.</p><div class="tests-material-actions">${button(`${icon('eye',14)} Lihat lengkap`,'test-material-preview','',t.material?'':'disabled')}${button('Atur materi','test-content')}</div></section><section class="card card-body"><h2>Tampilan saat ujian</h2><p class="small muted mt-sm">Pilihan satu soal atau semua soal per halaman diatur pada section di Ujian.</p>${own?`<div class="notice warn mt-sm"><strong>${own} soal memiliki materi sendiri</strong>Materi ini tidak cocok dengan tampilan semua soal dalam satu halaman.</div>`:`<div class="notice success mt-sm">Tidak ada materi per soal yang menghalangi tampilan semua soal.</div>`}<p class="small muted rule">Durasi section mengikuti Tes ini jika ujian memakai timer per section.</p></section></aside></div>`;}
function editorField(key,value,placeholder){const controls=[['bold','<b>B</b>','Tebal'],['italic','<i>I</i>','Miring'],['underline','<u>U</u>','Garis bawah'],['insertUnorderedList','• ≡','Daftar poin'],['insertOrderedList','1. ≡','Daftar bernomor'],['superscript','x²','Superscript'],['subscript','x₂','Subscript'],['formula','ƒx','Sisipkan rumus'],['image',icon('image',16),'Sisipkan gambar'],['table',icon('table',16),'Sisipkan tabel']];return `<div class="tests-editor" data-reference="RichTextEditor"><div class="tests-editor-toolbar" aria-label="Format teks">${controls.map(([format,label,title])=>`<button type="button" data-action="test-format" data-key="${key}" data-format="${format}" aria-label="${title}" title="${title}">${label}</button>`).join('')}<input type="file" accept="image/*" data-editor-image="${key}" aria-label="Pilih gambar untuk ${key==='material'?'materi':'instruksi'}" hidden></div><div class="tests-editable rich-content" data-test-editor="${key}" contenteditable="true" role="textbox" aria-label="${key==='material'?'Materi bersama':'Instruksi pengerjaan'}" aria-multiline="true" data-placeholder="${placeholder}">${cleanTestHTML(value)}</div></div>`;}
let testEditorRange=null;
document.addEventListener('mousedown',event=>{const button=event.target.closest('[data-action="test-format"]');if(button){event.preventDefault();const selection=window.getSelection();testEditorRange=selection.rangeCount?selection.getRangeAt(0).cloneRange():null;}});
function focusTestEditor(key){const editor=document.querySelector(`[data-test-editor="${key}"]`);editor.focus();const selection=window.getSelection();if(testEditorRange&&editor.contains(testEditorRange.commonAncestorContainer)){selection.removeAllRanges();selection.addRange(testEditorRange);}else if(!selection.anchorNode||!editor.contains(selection.anchorNode)){const range=document.createRange();range.selectNodeContents(editor);range.collapse(false);selection.removeAllRanges();selection.addRange(range);}return editor;}
function formatTestEditor(key,format){const editor=focusTestEditor(key);if(format==='image'){document.querySelector(`[data-editor-image="${key}"]`).click();return;}if(format==='table')document.execCommand('insertHTML',false,'<table><tbody><tr><th>Kolom 1</th><th>Kolom 2</th><th>Kolom 3</th></tr><tr><td>Isi</td><td>Isi</td><td>Isi</td></tr><tr><td>Isi</td><td>Isi</td><td>Isi</td></tr></tbody></table><p><br></p>');else if(format==='formula')document.execCommand('insertText',false,'\\(x^2\\)');else document.execCommand(format);testDraft[key]=editor.innerHTML;refreshTestSave();}
function testMaterialPreview(){openModal(`${modalHeader('Materi bersama',savedTest().title)}<div class="modal-body rich-content tests-full-material">${cleanTestHTML(savedTest().material)}</div><div class="modal-footer">${button('Tutup','close')}</div>`);}
function testsContent(){return `<div class="tests-content-layout"><section class="card"><div class="card-head"><h2>Materi bersama</h2><p class="small muted mt-sm">Bacaan, tabel, atau konteks untuk soal dalam Tes ini.</p></div><div class="card-body">${editorField('material',testDraft.material,'Tambahkan materi yang dipakai bersama...')}<p class="field-note">Materi milik soal menggantikan materi bersama hanya pada soal tersebut. Untuk semua soal satu halaman, gunakan materi bersama.</p></div></section><div class="stack"><section class="card tests-instructions"><div class="card-head"><h2>Instruksi pengerjaan</h2><p class="small muted mt-sm">Petunjuk yang dibaca siswa sebelum menjawab.</p></div><div class="card-body">${editorField('instructions',testDraft.instructions,'Tulis petunjuk untuk siswa...')}</div></section><section class="notice"><strong>Materi dan instruksi milik sumber Tes</strong>Perubahan akan digunakan pada seluruh ujian yang memakai Tes ini. Simpan sebelum membuka pratinjau.</section></div></div>`;}
function testsSettings(){const d=testDraft;return `<div class="tests-settings"><section class="card"><div class="card-head"><h2>Identitas & durasi</h2></div><div class="card-body tests-field-stack"><label>Judul tes<input data-test-field="title" value="${esc(d.title)}" required></label><div class="grid-2"><label>Mata pelajaran<input data-test-field="subject" value="${esc(d.subject)}" required></label><label>Topik<input data-test-field="topic" value="${esc(d.topic)}" required></label></div><label>Durasi (menit)<input type="number" min="1" step="1" data-test-field="duration" value="${d.duration}"><small>Menjadi durasi section bila ujian memakai timer per section. Timer seluruh ujian mengikuti durasi Exam.</small></label><label>Jenis section<select data-test-field="sectionType">${[['','Tidak ditentukan'],['reading','Reading'],['listening','Listening'],['writing','Writing']].map(([v,l])=>`<option value="${v}" ${d.sectionType===v?'selected':''}>${l}</option>`).join('')}</select><small>Klasifikasi untuk format sebelumnya; tidak menentukan navigasi atau timer composable. Listening tetap memerlukan audio.</small></label></div></section><section class="card"><div class="card-head"><h2>Audio section</h2><p class="small muted mt-sm">Audio bersama untuk seluruh soal pada Tes ini.</p></div><div class="card-body tests-field-stack"><label>URL audio<input type="url" data-test-field="audioUrl" value="${esc(d.audioUrl)}" placeholder="https://..."></label><div class="tests-upload"><label class="button">Unggah audio<input id="test-audio-file" type="file" accept="audio/*"></label>${button('Hapus audio','test-clear-audio')}</div><label>Batas pemutaran<select data-test-field="audioLimit">${[['','Tanpa batas'],['1','1 kali'],['2','2 kali'],['3','3 kali']].map(([v,l])=>`<option value="${v}" ${String(d.audioLimit)===v?'selected':''}>${l}</option>`).join('')}</select></label><p class="field-note">Aturan pemutaran mengikuti runtime existing. Pratinjau ini tidak menguji pembatasan pemutaran.</p></div></section></div><div id="test-settings-error" class="notice error mt" role="alert" hidden></div>`;}
function refreshTestSave(){const dirty=testSettingsDirty();const save=$('[data-action="test-save"]');if(save)save.disabled=!dirty;const preview=$('[data-action="test-preview"]');if(preview)preview.disabled=dirty||!savedTest().questions.length;const state=$('.tests-save-state');if(state)state.textContent=dirty?'Ada pengaturan belum disimpan':'Pengaturan tersimpan';}
function cleanTestHTML(value){const doc=new DOMParser().parseFromString(value,'text/html');const allowed=new Set(['P','BR','B','STRONG','I','EM','U','SUB','SUP','UL','OL','LI','H3','TABLE','THEAD','TBODY','TR','TH','TD','BLOCKQUOTE','IMG']);doc.querySelectorAll('script,style,iframe,object,embed').forEach(n=>n.remove());[...doc.body.querySelectorAll('*')].reverse().forEach(el=>{if(!allowed.has(el.tagName))el.replaceWith(...el.childNodes);else{const src=el.getAttribute('src'),alt=el.getAttribute('alt');[...el.attributes].forEach(a=>el.removeAttribute(a.name));if(el.tagName==='IMG'){if(src&&(/^(https?:|blob:)/.test(src)||src.startsWith('../../../web/public/'))){el.setAttribute('src',src);el.setAttribute('alt',alt||'Gambar materi');}else el.remove();}}});return doc.body.innerHTML;}
function saveTestSettings(){const d=testDraft;let error='';if(!d.title.trim()||!d.subject.trim()||!d.topic.trim())error='Isi judul, mata pelajaran, dan topik.';else if(!Number.isInteger(Number(d.duration))||Number(d.duration)<1)error='Durasi harus bilangan bulat positif.';else if(d.sectionType==='listening'&&!d.audioUrl.trim())error='Section Listening memerlukan audio.';else if(d.audioUrl&&!/^(https?:|blob:)/.test(d.audioUrl))error='Isi URL audio yang valid.';if(error){testsTab='settings';render();$('#test-settings-error').hidden=false;$('#test-settings-error').textContent=error;return;}Object.assign(savedTest(),d,{title:d.title.trim(),subject:d.subject.trim(),topic:d.topic.trim(),duration:Number(d.duration),material:cleanTestHTML(d.material),instructions:cleanTestHTML(d.instructions)});testDraft=testFields(savedTest());render();toast('Pengaturan Tes contoh disimpan.');}
function createTestModal(){openModal(`${modalHeader('Tes baru','Isi identitas Tes, lalu susun soal dan materi.')}<form id="test-create-form"><div class="modal-body tests-field-stack"><label>Judul tes<input name="title" required placeholder="Contoh: Literasi Bahasa Indonesia"></label><div class="grid-2"><label>Mata pelajaran<input name="subject" required></label><label>Topik<input name="topic" required></label></div><label>Durasi (menit)<input type="number" name="duration" min="1" step="1" required placeholder="20"></label><p class="small muted">Soal, materi bersama, instruksi, dan audio dapat diatur setelah Tes dibuat.</p></div><div class="modal-footer">${button('Batal','close')}<button class="button primary" type="submit">Buat & susun soal</button></div></form>`);}
function testBankModal(){
  const t=savedTest(),topics=[...new Set(testQuestionBank.map(q=>q.topic))];
  openModal(`${modalHeader('Pilih dari bank soal','Menambahkan soal ke Tes ini tanpa menghapusnya dari bank soal.')}<form id="test-bank-form"><div class="modal-body"><label>Cari soal<div class="admin-list-search">${icon('search',16)}<input id="test-bank-search" type="search" placeholder="Cari teks soal..." aria-label="Cari soal"></div></label><div class="tests-bank-filters"><label>Topik<select id="test-bank-topic"><option value="">Semua topik</option>${topics.map(topic=>`<option>${esc(topic)}</option>`).join('')}</select></label><label>Format / tipe soal<select id="test-bank-format"><option value="">Semua format</option>${Object.entries(testBankFormats).map(([format,label])=>`<option value="${format}">${label}</option>`).join('')}</select></label></div><div class="row between tests-bank-summary"><span id="test-bank-count" class="small muted" aria-live="polite"></span>${button('Reset pencarian & filter','test-bank-reset','text-button','type="button"')}</div><p id="test-bank-empty" class="small muted mt" hidden>Tidak ada soal yang cocok. Coba kata kunci atau filter lain.</p>${testQuestionBank.map(q=>{const exists=t.questions.some(item=>item.id===q.id);return `<div class="tests-bank-row" data-bank-question="${q.id}"><input type="checkbox" id="bank-${q.id}" name="question" value="${q.id}" ${exists?'disabled':''}><div class="tests-bank-content"><label for="bank-${q.id}" id="bank-body-${q.id}" class="tests-bank-text">${esc(q.body)}</label>${button('Lihat selengkapnya','test-bank-expand','text-button tests-bank-expand',`type="button" data-id="${q.id}" aria-expanded="false" aria-controls="bank-body-${q.id}" hidden`)}<div class="row mt-sm tests-bank-badges">${badge(testBankFormats[q.format],'gray')}<span class="small muted">${esc(q.topic)}</span>${exists?badge('Sudah ditambahkan','gray'):q.material?badge('Materi sendiri','warn'):''}</div></div></div>`}).join('')}</div><div class="modal-footer"><span id="test-bank-selected" class="small muted" aria-live="polite">0 soal dipilih</span><div class="row">${button('Batal','close')}<button class="button primary" type="submit" disabled>Tambahkan soal</button></div></div></form>`);
  filterTestBank();
}
function filterTestBank(){
  const search=$('#test-bank-search').value.trim().toLocaleLowerCase('id-ID'),topic=$('#test-bank-topic').value,format=$('#test-bank-format').value;
  let visible=0;
  document.querySelectorAll('[data-bank-question]').forEach(row=>{const q=testQuestionBank.find(q=>q.id===row.dataset.bankQuestion);row.hidden=!q.body.toLocaleLowerCase('id-ID').includes(search)||!!topic&&q.topic!==topic||!!format&&q.format!==format;if(!row.hidden)visible++;});
  $('#test-bank-empty').hidden=visible>0;
  $('#test-bank-count').textContent=`${visible} dari ${testQuestionBank.length} soal`;
  refreshTestBankSelection();
  requestAnimationFrame(()=>document.querySelectorAll('[data-bank-question]:not([hidden])').forEach(row=>{const text=row.querySelector('.tests-bank-text'),toggle=row.querySelector('[data-action="test-bank-expand"]');toggle.hidden=!text.classList.contains('expanded')&&text.scrollHeight<=text.clientHeight+1;}));
}
function refreshTestBankSelection(){const count=document.querySelectorAll('#test-bank-form input[name="question"]:checked').length;$('#test-bank-selected').textContent=`${count} soal dipilih`;$('#test-bank-form button[type="submit"]').disabled=!count;}
function testPreview(){const t=savedTest(),hasOwn=t.questions.some(q=>q.material),items=testPreviewAll?t.questions:[t.questions[testPreviewIndex]];openModal(`${modalHeader('Pratinjau Tes',t.title+' · tampilan sebenarnya mengikuti konfigurasi section di Ujian')}<div class="modal-body"><div class="tests-preview-controls"><span class="small muted">Simulasi tampilan</span><label><input type="radio" name="test-preview-mode" value="one" ${testPreviewAll?'':'checked'}>Satu soal</label><label><input type="radio" name="test-preview-mode" value="all" ${testPreviewAll?'checked':''} ${hasOwn?'disabled':''}>Semua soal</label></div>${hasOwn?'<p class="field-note mt-sm">Tampilan semua soal memerlukan materi bersama tanpa materi per soal.</p>':''}<div class="notice mt-sm">${t.instructions||'Tidak ada instruksi khusus.'}</div>${testPreviewAll||!items[0].material?`<div class="material tests-preview-material">${t.material||'Tidak ada materi bersama.'}</div>`:''}${items.map(q=>`<article class="tests-preview-q"><span class="tests-preview-index">Soal ${t.questions.indexOf(q)+1} dari ${t.questions.length}</span>${q.material?`<div class="material mt-sm">${q.material}</div>`:''}<h3>${esc(q.body)}</h3>${q.options.map((o,i)=>`<label class="answer"><input type="radio" name="preview-${q.id}"><span class="answer-letter">${'ABCD'[i]}</span>${esc(o)}</label>`).join('')}</article>`).join('')}</div><div class="modal-footer"><span class="small muted">Pratinjau tidak memulai sesi ujian.</span><div class="row">${!testPreviewAll?button('Sebelumnya','test-preview-prev','',testPreviewIndex?'':'disabled')+button('Berikutnya','test-preview-next','',testPreviewIndex===t.questions.length-1?'disabled':''):''}${button('Tutup','close')}</div></div>`);}
function renderTestsAndFilter(){render();if(view==='tests-list')filterTestsList();}
document.addEventListener('click',event=>{const el=event.target.closest('[data-action]');if(!el||el.disabled)return;const a=el.dataset.action,id=el.dataset.id;if(a==='tests-list'){route('tests-list');filterTestsList();}else if(a==='test-open'){closeModal();openTestPage(id);}else if(a==='test-create')createTestModal();else if(a==='test-tab'){testsTab=el.dataset.key;render();}else if(a==='test-content'){testsTab='content';render();}else if(a==='test-clear-search'){testQuery='';renderTestsAndFilter();$('#tests-list-search').focus();}else if(a==='test-filters'){const panel=$('#tests-filter-panel');panel.hidden=!panel.hidden;el.setAttribute('aria-expanded',String(!panel.hidden));}else if(a==='test-apply-filters'){$('#tests-filter-panel').hidden=true;$('[data-action="test-filters"]').setAttribute('aria-expanded','false');}else if(a==='test-clear-filters'){testSubject='';testTopic='';renderTestsAndFilter();}else if(a==='test-clear-filter'){if(el.dataset.key==='subject'){testSubject='';testTopic='';}else testTopic='';renderTestsAndFilter();}else if(a==='test-save')saveTestSettings();else if(a==='test-clear-audio'){testDraft.audioUrl='';render();}else if(a==='test-format')formatTestEditor(el.dataset.key,el.dataset.format);else if(a==='test-material-preview')testMaterialPreview();else if(a==='test-bank')testBankModal();else if(a==='test-bank-reset'){$('#test-bank-search').value='';$('#test-bank-topic').value='';$('#test-bank-format').value='';filterTestBank();}else if(a==='test-bank-expand'){const text=document.getElementById('bank-body-'+id),expanded=text.classList.toggle('expanded');el.setAttribute('aria-expanded',String(expanded));el.textContent=expanded?'Ringkas teks':'Lihat selengkapnya';}else if(a==='test-move'){const qs=savedTest().questions,i=qs.findIndex(q=>q.id===id),j=i+Number(el.dataset.direction);if(j>=0&&j<qs.length){[qs[i],qs[j]]=[qs[j],qs[i]];render();toast('Urutan soal contoh disimpan.');}}else if(a==='test-detach'){openModal(`${modalHeader('Lepas soal dari Tes?','Soal tetap tersedia di bank soal.')}<div class="modal-body small">Perubahan susunan berlaku pada Tes ini dan ujian yang memakainya.</div><div class="modal-footer">${button('Batal','close')}${button('Ya, lepas soal','test-confirm-detach','danger',`data-id="${id}"`)}</div>`);}else if(a==='test-confirm-detach'){savedTest().questions=savedTest().questions.filter(q=>q.id!==id);closeModal();render();toast('Soal dilepas dari Tes contoh.');}else if(a==='test-preview'||a==='test-question-preview'){testPreviewAll=false;testPreviewIndex=id?savedTest().questions.findIndex(q=>q.id===id):0;testPreview();}else if(a==='test-preview-next'||a==='test-preview-prev'){testPreviewIndex+=a==='test-preview-next'?1:-1;testPreview();}});
document.addEventListener('input',event=>{const el=event.target;if(el.id==='tests-list-search'){testQuery=el.value;filterTestsList();}else if(el.matches('[data-test-field]')){testDraft[el.dataset.testField]=el.value;refreshTestSave();}else if(el.matches('[data-test-editor]')){testDraft[el.dataset.testEditor]=el.innerHTML;refreshTestSave();}else if(el.id==='test-bank-search')filterTestBank();});
document.addEventListener('change',event=>{const el=event.target;if(el.matches('[data-editor-image]')&&el.files[0]){if(!el.files[0].type.startsWith('image/'))return;const key=el.dataset.editorImage,editor=focusTestEditor(key),src=URL.createObjectURL(el.files[0]);document.execCommand('insertHTML',false,`<img src="${esc(src)}" alt="${esc(el.files[0].name)}"><p><br></p>`);testDraft[key]=editor.innerHTML;el.value='';refreshTestSave();}else if(el.id==='test-bank-topic'||el.id==='test-bank-format')filterTestBank();else if(el.matches('#test-bank-form input[name="question"]'))refreshTestBankSelection();else if(el.id==='tests-subject'){testSubject=el.value;testTopic='';renderTestsAndFilter();$('#tests-filter-panel').hidden=false;$('[data-action="test-filters"]').setAttribute('aria-expanded','true');}else if(el.id==='tests-topic'){testTopic=el.value;renderTestsAndFilter();$('#tests-filter-panel').hidden=false;$('[data-action="test-filters"]').setAttribute('aria-expanded','true');}else if(el.matches('select[data-test-field]')){testDraft[el.dataset.testField]=el.value;refreshTestSave();}else if(el.id==='test-audio-file'&&el.files[0]){testDraft.audioUrl=URL.createObjectURL(el.files[0]);render();toast('Audio dipilih untuk contoh lokal.');}else if(el.name==='test-preview-mode'){testPreviewAll=el.value==='all';testPreview();}});
document.addEventListener('submit',event=>{if(event.target.id==='test-create-form'){event.preventDefault();const d=new FormData(event.target),id='test-'+Date.now();if(!['title','subject','topic'].every(k=>d.get(k).trim())||!Number.isInteger(Number(d.get('duration')))||Number(d.get('duration'))<1){toast('Lengkapi identitas dan durasi Tes.');return;}library.push({id,title:d.get('title').trim(),subject:d.get('subject').trim(),topic:d.get('topic').trim(),duration:Number(d.get('duration')),sectionType:'',material:'',instructions:'',audioUrl:'',audioLimit:'',questions:[]});closeModal();openTestPage(id);toast('Tes contoh dibuat. Tambahkan soal dari bank.');}else if(event.target.id==='test-bank-form'){event.preventDefault();const ids=new FormData(event.target).getAll('question'),bank=testQuestionBank;if(!ids.length){toast('Pilih setidaknya satu soal.');return;}ids.forEach(id=>{const q=bank.find(q=>q.id===id);if(q&&!savedTest().questions.some(item=>item.id===id))savedTest().questions.push(structuredClone(q));});closeModal();render();toast('Soal ditambahkan ke Tes contoh.');}});

document.addEventListener('click',event=>{const panel=document.getElementById('tests-filter-panel');if(panel&&!panel.hidden&&!event.target.closest('.tests-toolbar')){panel.hidden=true;document.querySelector('[data-action="test-filters"]').setAttribute('aria-expanded','false');}});
document.addEventListener('keydown',event=>{if(event.key==='Escape'){const panel=document.getElementById('tests-filter-panel');if(panel&&!panel.hidden){panel.hidden=true;document.querySelector('[data-action="test-filters"]').setAttribute('aria-expanded','false');}}});
